package net.civeira.phylax.feature.observe.observedembed.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbed;
import net.civeira.phylax.feature.observe.observedembed.domain.valueobject.AllowRawVO;

class AllowRawValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of allow raw of observed embed")
  void test_allow_raw_value_holder_assign_plain_value() {
    Object holder = new Object();
    AllowRawValueHolder<Object> value = new AllowRawValueHolder<>(holder);
    Assertions.assertSame(holder, value.allowRaw(true), "Setters must return the holder");
    Assertions.assertTrue(value.getAllowRawValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getAllowRaw().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of allow raw of observed embed")
  void test_allow_raw_value_holder_assign_value_object() {
    Object holder = new Object();
    AllowRawValueHolder<Object> value = new AllowRawValueHolder<>(holder);
    AllowRawVO vo = AllowRawVO.from(true);
    Assertions.assertFalse(value.getAllowRawValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.allowRaw(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAllowRawValue().orElseThrow());
    Assertions.assertSame(holder, value.allowRaw(Optional.empty()));
    Assertions.assertFalse(value.getAllowRawValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.allowRaw(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAllowRawValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of allow raw of observed embed against the original")
  void test_allow_raw_value_holder_read() {
    Object holder = new Object();
    AllowRawValueHolder<Object> value = new AllowRawValueHolder<>(holder);
    AllowRawVO vo = AllowRawVO.from(true);
    AllowRawVO other = AllowRawVO.from(true);
    ObservedEmbed original = Mockito.mock(ObservedEmbed.class);
    Mockito.when(original.getAllowRawValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAllowRaw(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readAllowRaw(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.allowRaw(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAllowRaw(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAllowRaw(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of allow raw of observed embed")
  void test_allow_raw_value_holder_unset() {
    Object holder = new Object();
    AllowRawValueHolder<Object> value = new AllowRawValueHolder<>(holder);
    AllowRawVO vo = AllowRawVO.from(true);
    value.allowRaw(vo);
    Assertions.assertSame(holder, value.unsetAllowRawIfMatches("allowRaw_other"));
    Assertions.assertTrue(value.getAllowRawValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAllowRawIfMatches("allowRaw"));
    Assertions.assertFalse(value.getAllowRawValue().isPresent(),
        "The field name must clear the value");
    value.allowRaw(vo);
    Assertions.assertSame(holder, value.unsetAllowRaw());
    Assertions.assertFalse(value.getAllowRawValue().isPresent(), "Unset must clear the value");
  }
}
